function hashId(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = ((h << 5) - h + str.charCodeAt(i)) | 0; }
  return Math.abs(h).toString(36);
}
const seenInBatch = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const job_url = (j.job_url || '').trim();
  if (!job_url) continue;
  if (seenInBatch.has(job_url)) continue; // dedupe within this run
  seenInBatch.add(job_url);
  out.push({ json: {
