const rejectTerms = ["us only", "canada only", "uk only", "eu only", "europe only", "australia only", "must be based in", "must live in", "must be authorized to work in", "local work permit required", "hybrid", "onsite", "office required", "remote within country only", "fixed us hours", "fixed eu hours"];
const whitelistTerms = ["worldwide remote", "global remote", "work from anywhere", "anywhere", "apac remote", "international contractors accepted", "contractor role", "b2b contractor", "hires via deel", "hires via remote.com", "hires via oyster", "eor supported", "remote first", "distributed team"];
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const haystack = ((j.job_title || '') + ' ' + (j.description || '') + ' ' + (j.location_text || '')).toLowerCase();
  const hasWhitelist = whitelistTerms.some(t => haystack.includes(t));
  const hitReject = rejectTerms.find(t => haystack.includes(t));
  const hardReject = !!hitReject && !hasWhitelist;
  out.push({ json: { ...j,
    hard_filter_result: hardReject ? 'reject' : 'pass',
    hard_filter_hit: hitReject || '',
    hard_filter_whitelisted: hasWhitelist,
  }});
}
return out;

