const coreTerms = ["data analyst", "data scientist", "junior data scientist", "business intelligence analyst", "bi analyst", "marketing analyst", "performance marketing analyst", "growth analyst", "ai marketing specialist", "ai automation specialist", "ai workflow consultant", "creative strategist with data", "martech analyst"];
const adjacentTerms = ["marketing", "data", "analytics", "automation", "artificial intelligence", " ai ", "growth", "seo", "ppc", "crm", "dashboard", "reporting"];
