function parseMonthlySalary(text) {
  if (!text) return 0;
  const nums = (text.match(/[\d,]{3,}/g) || []).map(n => parseInt(n.replace(/,/g, ''), 10)).filter(Boolean);
  if (!nums.length) return 0;
  const max = Math.max(...nums);
  return max >= 12000 ? Math.round(max / 12) : max; // guess annual vs monthly
}
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let taiwanPoints = 0;
  const haystack = ((j.job_title || '') + ' ' + (j.description || '')).toLowerCase();
  if (j.taiwan_eligible === 'yes' && j.location_risk === 'low') taiwanPoints = 40;
  else if (j.taiwan_eligible === 'yes' && haystack.includes('apac')) taiwanPoints = 30;
  else if (j.taiwan_eligible === 'unclear' && j.location_risk !== 'high') taiwanPoints = 20;
  else taiwanPoints = 0;
  const monthly = parseMonthlySalary(j.salary);
  let salaryPoints = 0;
  if (monthly >= 5000) salaryPoints = 25;
  else if (monthly >= 3000) salaryPoints = 15;
  else if (j.salary) salaryPoints = 10;
  const rawScore = taiwanPoints + (j.async_points || 0) + (j.role_points || 0) + salaryPoints;
  const score = Math.min(100, rawScore);
  out.push({ json: { ...j, taiwan_points: taiwanPoints, salary_points: salaryPoints, score }});
}
return out;

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let decision, reject_reason = '', application_status;
  const asyncOk = j.async_level === 'high' || j.async_level === 'medium';
  const timezoneOk = j.timezone_risk === 'low' || j.timezone_risk === 'medium';
  if (j.taiwan_eligible === 'no' || j.location_risk === 'high' || j.timezone_risk === 'high' || j.score < 70) {
    decision = 'reject';
    if (j.taiwan_eligible === 'no') reject_reason = 'taiwan_ineligible: ' + (j.taiwan_reason || '');
    else if (j.location_risk === 'high') reject_reason = 'location_risk_high: ' + (j.taiwan_reason || '');
    else if (j.timezone_risk === 'high') reject_reason = 'timezone_risk_high';
    else reject_reason = 'low_score: ' + j.score;
    application_status = 'rejected';
  } else if (j.taiwan_eligible === 'yes' && j.score >= 85 && asyncOk && j.location_risk === 'low' && timezoneOk) {
    decision = 'apply';
    application_status = 'ready_to_apply';
  } else if (j.taiwan_eligible === 'unclear' && j.score >= 85 && j.location_risk === 'medium') {
    decision = 'manual_check';
    application_status = 'needs_manual_review';
  } else if (j.score >= 70) {
    decision = 'manual_check';
    application_status = 'needs_manual_review';
  } else {
    decision = 'reject';
    reject_reason = 'below_apply_threshold: ' + j.score;
    application_status = 'rejected';
  }
  const why = [];
  if (j.role_category && j.role_category !== 'other') why.push('role fit: ' + j.role_category);
  if (j.async_level === 'high') why.push('clearly async');
  if (j.taiwan_points >= 30) why.push('worldwide/APAC friendly');
  if (j.salary_points >= 15) why.push('salary above target');
  out.push({ json: { ...j, decision, reject_reason, application_status,
    date_rejected: decision === 'reject' ? new Date().toISOString().slice(0, 10) : '',
    why_good_fit: why.join('; '),
  }});
}
return out;

